16	public class SseBroadcasterImpl implements SseBroadcaster {
17	
18	    private final List<SseEventSink> sinks = new ArrayList<>();
19	    private final List<BiConsumer<SseEventSink, Throwable>> onErrorListeners = new ArrayList<>();
20	    private final List<Consumer<SseEventSink>> onCloseListeners = new ArrayList<>();
21	    private volatile boolean isClosed;
22	
23	    @Override
24	    public synchronized void onError(BiConsumer<SseEventSink, Throwable> onError) {
25	        Objects.requireNonNull(onError);
26	        checkClosed();
27	        onErrorListeners.add(onError);
28	    }
29	
30	    @Override
31	    public synchronized void onClose(Consumer<SseEventSink> onClose) {
32	        Objects.requireNonNull(onClose);
33	        checkClosed();
34	        onCloseListeners.add(onClose);
35	    }
36	
37	    @Override
38	    public synchronized void register(SseEventSink sseEventSink) {
39	        Objects.requireNonNull(sseEventSink);
40	        checkClosed();
41	        if (sseEventSink instanceof SseEventSinkImpl == false) {
42	            throw new IllegalArgumentException("Can only work with Quarkus-REST instances: " + sseEventSink);
43	        }
44	        ((SseEventSinkImpl) sseEventSink).register(this);
45	        sinks.add(sseEventSink);
46	    }
