49	    public synchronized CompletionStage<?> broadcast(OutboundSseEvent event) {
50	        Objects.requireNonNull(event);
51	        checkClosed();
52	        CompletableFuture<?>[] cfs = new CompletableFuture[sinks.size()];
53	        for (int i = 0; i < sinks.size(); i++) {
54	            SseEventSink sseEventSink = sinks.get(i);
55	            CompletionStage<?> cs;
56	            try {
57	                cs = sseEventSink.send(event).exceptionally((t) -> {
58	                    // do not propagate the exception to the returned CF
59	                    // apparently, the goal is to close this sink and not report the error
60	                    // of the broadcast operation
61	                    notifyOnErrorListeners(sseEventSink, t);
62	                    return null;
63	                });
64	            } catch (Exception e) {
65	                // do not propagate the exception to the returned CF
66	                // apparently, the goal is to close this sink and not report the error
67	                // of the broadcast operation
68	                notifyOnErrorListeners(sseEventSink, e);
69	                cs = CompletableFuture.completedFuture(null);
70	            }
71	            cfs[i] = cs.toCompletableFuture();
72	        }
73	        return CompletableFuture.allOf(cfs);
