76	    private void notifyOnErrorListeners(SseEventSink eventSink, Throwable throwable) {
77	        // We have to notify close listeners if the SSE event output has been
78	        // closed (either by client closing the connection (IOException) or by
79	        // calling SseEventSink.close() (IllegalStateException) on the server
80	        // side).
81	        if (throwable instanceof IOException || throwable instanceof IllegalStateException) {
82	            notifyOnCloseListeners(eventSink);
83	        }
84	        onErrorListeners.forEach(consumer -> {
85	            consumer.accept(eventSink, throwable);
86	        });
87	    }
88	
89	    private void notifyOnCloseListeners(SseEventSink eventSink) {
90	        // First remove the eventSink from the outputQueue to ensure that
91	        // concurrent calls to this method will notify listeners only once for a
92	        // given eventSink instance.
93	        if (sinks.remove(eventSink)) {
94	            onCloseListeners.forEach(consumer -> {
95	                consumer.accept(eventSink);
96	            });
97	        }
98	    }
