100	    private void checkClosed() {
101	        if (isClosed) {
102	            throw new IllegalStateException("Broadcaster has been closed");
103	        }
104	    }
105	
106	    @Override
107	    public synchronized void close() {
108	        close(true);
109	    }
110	
111	    @Override
112	    public synchronized void close(boolean cascading) {
113	        if (isClosed) {
114	            return;
115	        }
116	        isClosed = true;
117	        if (cascading) {
118	            for (SseEventSink sink : sinks) {
119	                // this will in turn fire close events to our listeners
