121	            }
122	        }
123	    }
124	
125	    synchronized void fireClose(SseEventSinkImpl sseEventSink) {
126	        for (Consumer<SseEventSink> listener : onCloseListeners) {
127	            listener.accept(sseEventSink);
128	        }
129	    }
130	}
